mapper.sql:
SELECT 'WHAT_IF' AS history_type, s.simulation_id AS source_id, s.scenario_name, NULL AS analysis_type, s.created_at, s.expected_asset, s.monthly_spending_amount, s.monthly_saving_amount, s.monthly_investment_amount, NULL AS generation_source, NULL AS result_json, EXISTS ( SELECT 1 FROM strategy_application sa LEFT JOIN ai_analysis applied_analysis ON applied_analysis.analysis_id = sa.analysis_id AND applied_analysis.user_id = sa.user_id WHERE sa.user_id = s.user_id AND ( sa.simulation_id = s.simulation_id OR applied_analysis.simulation_id = s.simulation_id ) ) AS applied FROM simulation s WHERE s.user_id = #{userId} AND s.is_saved = TRUE
UNION ALL
SELECT 'AI' AS history_type, a.analysis_id AS source_id, NULL AS scenario_name, a.analysis_type, a.created_at, NULL AS expected_asset, NULL AS monthly_spending_amount, NULL AS monthly_saving_amount, NULL AS monthly_investment_amount, a.generation_source, a.result_json, EXISTS ( SELECT 1 FROM strategy_application sa WHERE sa.user_id = a.user_id AND sa.analysis_id = a.analysis_id ) AS applied FROM ai_analysis a WHERE a.user_id = #{userId}
